<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {api,mode} from '../api'
import {safeUrl} from '../api/utils'
import {categories} from '../types/research'
import type {PaperSummary,DocumentSummary,EvidenceRecord,PageResult,AnalysisResult} from '../types/research'
import {useResource} from '../composables/useResource'
import {useEvidenceStore} from '../stores/evidence'
import {useTaskStore} from '../stores/tasks'
import AsyncState from '../components/AsyncState.vue'
import EvidenceCitation from '../components/EvidenceCitation.vue'
import AnalysisCard from '../components/AnalysisCard.vue'
import PdfViewer from '../components/PdfViewer.vue'
import TaskProgress from '../components/TaskProgress.vue'
import PaperPublication from '../components/PaperPublication.vue'
import ClaimReviewPanel from '../components/ClaimReviewPanel.vue'
const route=useRoute(),router=useRouter(),evidence=useEvidenceStore(),tasks=useTaskStore()
const id=computed(()=>Number(route.params.paperId)),tab=computed({get:()=>String(route.query.tab||'overview'),set:v=>router.replace({query:{...route.query,tab:v}})}),page=computed({get:()=>Math.max(1,Number(route.query.page)||1),set:v=>router.replace({query:{...route.query,page:String(v)}})})
const {data,loading,error,load}=useResource<PaperSummary|null>(null),docs=ref<DocumentSummary[]>([]),docId=ref<number>(),analyses=ref<AnalysisResult[]>([])
const {data:chunks,loading:chunkLoading,error:chunkError,load:loadChunks}=useResource<PageResult<EvidenceRecord>>({items:[],total:0,page:1,page_size:10})
const chunkPage=ref(1),selectedFile=ref<File|null>(null),preview=ref<string|null>(null),confirmed=ref(false),url=ref(''),uploading=ref(false),taskId=ref(''),fileInput=ref<HTMLInputElement|null>(null)
const doc=computed(()=>docs.value.find(d=>d.id===docId.value)),task=computed(()=>tasks.tasks[taskId.value]),pdfUrl=computed(()=>preview.value||(doc.value?.pdf_file_url?safeUrl(doc.value.pdf_file_url):null))
const fetching=ref(false),taskActive=computed(()=>['queued','running'].includes(task.value?.status||''))
const activeAnalysis=computed(()=>analyses.value.find(a=>a.is_current!==false)||analyses.value[0])
const docsLoading=ref(false),docsError=ref(''),analysesLoading=ref(false),analysesError=ref('')
let docsVersion=0,analysisVersion=0
async function refresh(){const paperId=id.value;await load(()=>api.paper(paperId));if(id.value===paperId&&data.value&&!error.value){await loadTab();if(route.query.evidenceId)await evidence.open(String(route.query.evidenceId))}}
async function fetchDocuments(){const paperId=id.value,version=++docsVersion;docsLoading.value=true;docsError.value='';try{const result=await api.documents(paperId);if(id.value!==paperId||version!==docsVersion)return;docs.value=result;docId.value=result.some(d=>d.id===docId.value)?docId.value:result[0]?.id}catch(e){if(id.value===paperId&&version===docsVersion)docsError.value='文档列表暂时无法加载：'+(e as Error).message}finally{if(version===docsVersion)docsLoading.value=false}}
async function fetchAnalyses(){const paperId=id.value,version=++analysisVersion;analysesLoading.value=true;analysesError.value='';try{const result=await api.analyses(paperId);if(id.value===paperId&&version===analysisVersion)analyses.value=result}catch(e){if(id.value===paperId&&version===analysisVersion)analysesError.value='分析记录暂时无法加载：'+(e as Error).message}finally{if(version===analysisVersion)analysesLoading.value=false}}
async function loadTab(){if(!data.value||data.value.id!==id.value)return;if(['pdf','evidence'].includes(tab.value))await fetchDocuments();else if(tab.value==='analysis')await fetchAnalyses()}
watch(tab,loadTab)

async function fetchChunks(){const documentId=docId.value;if(documentId)await loadChunks(()=>api.chunks(documentId,{page:chunkPage.value,page_size:10}));else await loadChunks(async()=>({items:[],total:0,page:1,page_size:10}))}
async function selectFile(file?:File){if(fileInput.value)fileInput.value.value='';if(!file||uploading.value||fetching.value||taskActive.value)return;if(file.size>20*1024*1024){ElMessage.error('PDF 大小不能超过 20 MB');return}if(await file.slice(0,5).text()!=='%PDF-'){ElMessage.error('请选择有效的 PDF 文件');return}if(preview.value)URL.revokeObjectURL(preview.value);selectedFile.value=file;preview.value=URL.createObjectURL(file);confirmed.value=false}
async function upload(){if(!selectedFile.value||!confirmed.value)return;const paperId=id.value;uploading.value=true;try{const r=await api.upload(paperId,selectedFile.value);if(id.value===paperId)taskId.value=r.task_id;await tasks.track(r.task_id)}catch(e){ElMessage.error((e as Error).message)}finally{uploading.value=false}}
async function acquireFulltext(){if(fetching.value||uploading.value||taskActive.value)return;const paperId=id.value;fetching.value=true;tab.value='pdf';try{const r=await api.fetchFulltext(paperId);if(id.value===paperId)taskId.value=r.task_id;await tasks.track(r.task_id)}catch(e){ElMessage.error((e as Error).message)}finally{fetching.value=false}}
async function importUrl(){if(!safeUrl(url.value)||!/^https?:\/\//.test(url.value)){ElMessage.warning('请输入 http/https 全文地址');return}uploading.value=true;try{const r=await api.importUrl(id.value,url.value);taskId.value=r.task_id;await tasks.track(r.task_id)}catch(e){ElMessage.error((e as Error).message)}finally{uploading.value=false}}
watch(()=>task.value?.status,async status=>{if(status==='succeeded'){const paperId=id.value,resultId=Number(task.value?.result_id);if(preview.value)URL.revokeObjectURL(preview.value);preview.value=null;selectedFile.value=null;confirmed.value=false;await refresh();if(id.value===paperId&&docs.value.some(d=>d.id===resultId))docId.value=resultId;ElMessage.success('全文已保存，可以查看 PDF 和证据片段')}})
watch(docId,()=>{chunkPage.value=1;fetchChunks()});watch(chunkPage,fetchChunks);watch(id,()=>{docsVersion++;analysisVersion++;docsLoading.value=false;analysesLoading.value=false;docsError.value='';analysesError.value='';taskId.value='';docs.value=[];docId.value=undefined;analyses.value=[];data.value=null;chunks.value={items:[],total:0,page:1,page_size:10};selectedFile.value=null;if(preview.value)URL.revokeObjectURL(preview.value);preview.value=null;refresh()},{immediate:true})
onBeforeUnmount(()=>{if(preview.value)URL.revokeObjectURL(preview.value)})
</script>
<template><RouterLink class="back-link" to="/library">← 返回文献库</RouterLink><AsyncState :loading="loading" :error="error" @retry="refresh"><template v-if="data"><div class="paper-detail-heading"><div class="eyebrow">P{{data.id}} · RESEARCH PAPER</div><h1>{{data.title}}</h1><p>{{data.authors.join(' · ')||'作者信息未记录'}}<span class="metadata-dot">·</span>{{data.year||'年份未记录'}}</p><div class="flex-between"><div class="tag-row"><el-tag type="info" effect="plain">已收藏</el-tag><el-tag v-if="data.has_fulltext" type="success" effect="plain">已获取全文</el-tag><el-tag v-if="data.has_analysis" effect="plain">已分析</el-tag><code>{{data.doi||'DOI 未记录'}}</code></div><div class="button-row"><el-button type="primary" :loading="fetching" :disabled="uploading||taskActive" @click="acquireFulltext">获取原文</el-button><RouterLink v-if="data.has_fulltext" class="primary-link" :to="`/analysis?paperId=${data.id}`">分析论文 ↗</RouterLink><el-button v-else @click="tab='pdf'">上传 PDF</el-button></div></div></div><PaperPublication :paper-id="data.id"/><el-tabs v-model="tab" class="detail-tabs"><el-tab-pane label="基本信息" name="overview"/><el-tab-pane label="全文阅读" name="pdf"/><el-tab-pane label="证据片段" name="evidence"/><el-tab-pane label="AI 分析" name="analysis"/></el-tabs><div v-if="tab==='overview'" class="detail-overview"><section class="panel prose-panel"><div class="eyebrow">ABSTRACT & OVERVIEW</div><h2>研究概览</h2><p>{{data.abstract||'暂未记录摘要。可上传论文全文，解析后阅读原始内容。'}}</p></section><aside class="panel prose-panel"><h3>文献信息</h3><dl class="details-list"><dt>论文编号</dt><dd>P{{data.id}}</dd><dt>DOI</dt><dd>{{data.doi||'未记录'}}</dd><dt>OpenAlex ID</dt><dd>{{data.openalex_id||'未记录'}}</dd><dt>引用次数</dt><dd>{{data.citation_count}}</dd><dt>原文来源</dt><dd><a v-if="safeUrl(data.url)" :href="safeUrl(data.url)!" target="_blank" rel="noopener noreferrer">打开原站 ↗</a><span v-else>本地文献</span></dd></dl></aside></div><div v-else-if="tab==='pdf'" class="pdf-layout"><div><div v-if="docsError" class="inline-error" role="alert"><span>{{docsError}}</span><el-button size="small" @click="fetchDocuments">重试</el-button></div><p v-if="docsLoading" class="note" role="status">正在加载文档列表…</p><el-select v-if="docs.length>1" v-model="docId" aria-label="选择全文文档"><el-option v-for="d in docs" :key="d.id" :value="d.id" :label="`文档 ${d.id} · ${d.parser}`"/></el-select><PdfViewer :file-url="pdfUrl" :page="page" :page-count="doc?.page_count||null" @page-change="page=$event"/></div><aside><section class="panel upload-panel"><h3>获取论文全文</h3><el-button :loading="fetching" :disabled="uploading||taskActive" @click="acquireFulltext">获取原文</el-button><p class="note">明确的 CVPR/ICCV 官方来源优先从 CVF 获取 PDF；其他来源依次尝试 OpenAlex、DOI 原站和 arXiv，下载并解析。找不到时可手动上传。</p><div class="form-divider">或上传本地 PDF</div><p class="muted">请确认上传文件与当前论文一致。</p><input ref="fileInput" type="file" accept="application/pdf,.pdf" hidden @change="selectFile(($event.target as HTMLInputElement).files?.[0])"/><button class="upload-drop" @click="fileInput?.click()" @dragover.prevent @drop.prevent="selectFile($event.dataTransfer?.files[0])"><span>＋</span><strong>{{selectedFile?.name||'选择或拖拽 PDF 文件'}}</strong><small>{{selectedFile?`${(selectedFile.size/1024/1024).toFixed(2)} MB`:'支持 PDF · 最大 20 MB'}}</small></button><el-checkbox v-model="confirmed" :disabled="!selectedFile">我已确认 PDF 对应当前论文</el-checkbox><el-button type="primary" :disabled="!selectedFile||!confirmed||fetching||taskActive" :loading="uploading" @click="upload">上传并解析全文</el-button><p v-if="mode()==='demo'" class="note">当前可本地预览；解析与入库需要真实 API。</p><div class="form-divider">或导入公开全文链接</div><el-input v-model="url" placeholder="https://…" aria-label="公开全文地址"/><el-button :loading="uploading" @click="importUrl">导入网页全文</el-button></section><TaskProgress v-if="task" :task="task"/><p class="note">使用浏览器 PDF 阅读器预览。外部页码用于跳转，不随阅读器滚动更新，也不会高亮原句。</p></aside></div><div v-else-if="tab==='evidence'"><div class="result-toolbar"><span class="muted">{{chunks.total}} 个可查看片段 <span v-if="mode()==='demo'">· 仅包含已导出快照中的证据</span></span><el-select v-if="docs.length>1" v-model="docId" aria-label="选择文档"><el-option v-for="d in docs" :key="d.id" :value="d.id" :label="`文档 ${d.id} · ${d.parser}`"/></el-select></div><AsyncState :loading="docsLoading||chunkLoading" :error="docsError||chunkError" :empty="!chunks.items.length" title="暂无可查看的证据片段" @retry="docsError?fetchDocuments():fetchChunks()"><div class="evidence-list"><article v-for="c in chunks.items" :key="c.evidence_id" class="panel chunk-card"><div class="flex-between"><EvidenceCitation :ref-id="`P${data.id}:${c.evidence_id}`"/><span class="muted">{{c.page_number===null?'网页 · 无页码':`第 ${c.page_number} 页`}} · {{c.section_hint||'未识别章节'}}</span></div><p>{{c.quote}}</p><el-button v-if="c.page_number!==null" size="small" @click="page=c.page_number;tab='pdf'">在 PDF 中查看 →</el-button></article></div><el-pagination v-model:current-page="chunkPage" :total="chunks.total" :page-size="10" layout="prev,pager,next"/></AsyncState></div><div v-else-if="tab==='analysis'"><AsyncState :loading="analysesLoading" :error="analysesError" @retry="fetchAnalyses"><p v-if="activeAnalysis?.is_current===false" class="note warning">这份分析对应旧版原文，请重新分析。</p><ClaimReviewPanel v-if="activeAnalysis" :analysis="activeAnalysis"/><div v-if="activeAnalysis" class="analysis-grid"><AnalysisCard v-for="(label,k,i) in categories" :key="k" :number="i+1" :title="label" :findings="activeAnalysis.analysis[k]" :paper-id="data.id"/></div><AsyncState v-else empty title="这篇论文还没有分析结果"><template #action><RouterLink class="primary-link" :to="`/analysis?paperId=${data.id}`">开始论文分析 →</RouterLink></template></AsyncState></AsyncState></div></template></AsyncState></template>
